<template>
  <q-page>
    <div v-if="!ready">
      <h2 class="row items-center q-mb-lg">
        <q-skeleton type="QChip" width="90px" height="50px" class="q-mr-md" />
        <q-skeleton type="text" width="420px" height="60px" />
      </h2>
      <editor-skeleton />
    </div>
    <div v-else>
