      :exact-rows="schemaExactRows"
      :counting-rows="schemaCountingRows"
      @count="countSchemaRows"
      @drop="dropOrphan"
      @update="applySchema('update')"
      @recreate="(tables) => applySchema('recreate', tables)" />
    <control-diff-dialog
      ref="controlDiffDialog"
      :diff="unsavedChanges"
      :busy="saving"
      @apply="persist('stay')"
      @undo="undoChange"
      @discard="discardAll" />
    <control-versions-dialog
      ref="versionsDialog"
